selector .elementor-widget-text-editor ul,
selector .elementor-widget-text-editor ol,
selector .elementor-widget-theme-post-content ul,
selector .elementor-widget-theme-post-content ol,
selector .elementor-widget-woocommerce-product-content ul,
selector .elementor-widget-woocommerce-product-content ol {
    margin-bottom: .9rem;
}

selector .elementor-widget-text-editor .elementor-widget-container > :last-child,
selector .elementor-widget-theme-post-content .elementor-widget-container > :last-child,
selector .elementor-widget-woocommerce-product-content .elementor-widget-container > :last-child,
selector .elementor-widget-text-editor > :last-child,
selector .elementor-widget-theme-post-content > :last-child,
selector .elementor-widget-woocommerce-product-content > :last-child {
    margin-bottom: 0;
}

selector .elementor-widget-text-editor img[class*='align'],
selector .elementor-widget-theme-post-content img[class*='align'],
selector .elementor-widget-woocommerce-product-content img[class*='align'] {
    margin-bottom: 1.5rem;
}

selector .elementor-widget-text-editor img.alignright,
selector .elementor-widget-theme-post-content img.alignright,
selector .elementor-widget-woocommerce-product-content img.alignright {
    margin-left: 1.5rem;
}

selector .elementor-widget-text-editor img.alignleft,
selector .elementor-widget-theme-post-content img.alignleft,
selector .elementor-widget-woocommerce-product-content img.alignleft {
    margin-right: 1.5rem;
}

selector .elementor-widget-text-editor,
selector .elementor-widget-theme-post-content,
