selector .gform-theme.gform-theme--framework {
    /* font primary */
    --gf-font-family-primary: var(--e-global-typography-d67dc01-font-family) !important;
    --gf-font-size-primary: var(--e-global-typography-d67dc01-font-size) !important;
    --gf-font-weight-primary: var(--e-global-typography-d67dc01-font-weight) !important;
    --gf-line-height-primary: var(--e-global-typography-d67dc01-line-height) !important;

    /* font secondary*/
    --gf-font-family-secondary: var(--e-global-typography-86330fc-font-family) !important;
    --gf-font-size-secondary: var(--e-global-typography-86330fc-font-size) !important;
    --gf-font-weight-secondary: var(--e-global-typography-86330fc-font-weight) !important;
    --gf-line-height-secondary: var(--e-global-typography-86330fc-line-height) !important;

    /* font tertiary */
    --gf-font-family-tertiary: var(--e-global-typography-86330fc-font-family) !important;
    --gf-font-size-tertiary: var(--e-global-typography-86330fc-font-size) !important;
    --gf-font-weight-tertiary: var(--e-global-typography-86330fc-font-weight) !important;
    --gf-line-height-tertiary: var(--e-global-typography-86330fc-line-height) !important;

    /* border */
    --gf-radius: 0 !important;

    /* gap */
    --gf-form-gap-y: 20px !important;
    --gf-form-gap-x: 40px !important;

    /* primary color */
    --gf-color-primary: hsl(219, 78%, 51%) !important;
    --gf-color-primary-rgb: 34, 102, 227 !important;
    --gf-color-primary-contrast: #fff !important;
    --gf-color-primary-contrast-rgb: 255, 255, 255 !important;
    --gf-color-primary-darker: hsl(219, 78%, 41%) !important;
    --gf-color-primary-lighter: hsl(219, 78%, 61%) !important;

    /* secondary color */
    --gf-color-secondary: #000000 !important;
    --gf-color-secondary-rgb: 0, 0, 0 !important;
    --gf-color-secondary-contrast: #fff !important;
    --gf-color-secondary-contrast-rgb: 255, 255, 255 !important;
    --gf-color-secondary-darker: #000000 !important;
    --gf-color-secondary-lighter: #1a1a1a !important;

    /* control size */
    --gf-ctrl-size: var(--gf-ctrl-size-xl) !important;

    /* label */
    --gf-ctrl-label-color-primary: #000 !important;
    --gf-ctrl-label-color-secondary: #000 !important;
    --gf-ctrl-label-font-weight-primary: 600 !important;

    /* danger color */
    /* --gf-color-danger: #f55f3d !important;
    --gf-color-danger-rgb: 192, 43, 10 !important;
    --gf-color-danger-contrast: #fff !important;
    --gf-color-danger-contrast-rgb: 255, 255, 255 !important; */

    /* success color */
    /* --gf-color-success: #399f4b !important;
    --gf-color-success-rgb: 57, 159, 75 !important;
    --gf-color-success-contrast: #fff !important;
    --gf-color-success-contrast-rgb: 255, 255, 255 !important; */

    /* control description */
    /* --gf-color-out-ctrl-light: rgba(17, 35, 55, 0.1);
    --gf-color-out-ctrl-light-rgb: 17, 35, 55;
    --gf-color-out-ctrl-light-darker: rgba(104, 110, 119, 0.35);
    --gf-color-out-ctrl-light-lighter: #F5F5F5;
    --gf-color-out-ctrl-dark: #fff !important;
    --gf-color-out-ctrl-dark-rgb: 255, 255, 255 !important;
    --gf-color-out-ctrl-dark-darker: #000000 !important;
    --gf-color-out-ctrl-dark-lighter: #1a1a1a !important; */

    /* control input */
    /* --gf-color-in-ctrl: hsl(30, 17%, 98%);
    --gf-color-in-ctrl-rgb: 255, 255, 255;
    --gf-color-in-ctrl-contrast: #000;
    --gf-color-in-ctrl-contrast-rgb: 17, 35, 55;
    --gf-color-in-ctrl-darker: hsl(30, 17%, 88%);
    --gf-color-in-ctrl-lighter: hsl(30, 17%, 100%);
    --gf-color-in-ctrl-primary: hsl(219, 78%, 51%);
    --gf-color-in-ctrl-primary-rgb: 32, 76, 229;
    --gf-color-in-ctrl-primary-contrast: #fff;
    --gf-color-in-ctrl-primary-contrast-rgb: 255, 255, 255;
    --gf-color-in-ctrl-primary-darker: hsl(219, 78%, 41%);
    --gf-color-in-ctrl-primary-lighter: hsl(219, 78%, 61%);
    --gf-color-in-ctrl-light: rgba(17, 35, 55, 0.1);
    --gf-color-in-ctrl-light-rgb: 17, 35, 55;
    --gf-color-in-ctrl-light-darker: rgba(104, 110, 119, 0.35);
    --gf-color-in-ctrl-light-lighter: #F5F5F5;
    --gf-color-in-ctrl-dark: #585e6a;
    --gf-color-in-ctrl-dark-rgb: 88, 94, 106;
    --gf-color-in-ctrl-dark-darker: #000;
    --gf-color-in-ctrl-dark-lighter: rgba(17, 35, 55, 0.65); */

    /* button size */
    --gf-ctrl-btn-size: var(--gf-ctrl-size-xl) !important;

    /* button font */
    --gf-ctrl-btn-font-weight:  var(--e-global-typography-8c04b68-font-weight) !important;
    --gf-ctrl-btn-font-size:  var(--e-global-typography-8c04b68-font-size) !important;
    --gf-ctrl-btn-font-family:  var(--e-global-typography-8c04b68-font-family) !important;
    --gf-ctrl-btn-line-height: var(--e-global-typography-8c04b68-line-height) !important;
    --gf-ctrl-btn-text-transform:  var(--e-global-typography-8c04b68-text-transform) !important;
}

selector input[type=date]:focus, 
selector input[type=email]:focus, 
selector input[type=number]:focus, 
selector input[type=password]:focus, 
selector input[type=search]:focus, 
selector input[type=tel]:focus, 
