    min-width: 200px !important;
}

selector .gform-theme--foundation .gform_footer input[type="submit"][id*="gform_submit_button_"].button.gform-button--width-full {
    inline-size: 100% !important;
}

selector .gfield--type-html > :last-child {
    margin-bottom: 0;
}

selector .gform_confirmation_wrapper {
    text-align: center;
}

selector .gform_required_legend {
    display: none;
}

selector .gform_description:empty {
    display: none;
}
