item.content:encoded:
/* ==========================================================================
  HOME PAGE SPLIT IMAGES  ========================================================================== */

/* Left Overlapping Split Image - Homepage */
img.home-split-img-left {
    clip-path: polygon(0 0, 100% 0, 50% 100%, 0 100%) !important;
    position: relative !important;
    z-index: 1 !important;
}

/* Right Overlapping Split Image - Homepage */
img.home-split-img-right {
    clip-path: polygon(50% 0, 100% 0, 100% 100%, 0 100%) !important;
    position: relative !important;
    z-index: 2 !important;
}


/* ==========================================================================
   DESIGN 1: slide up on hover   ========================================================================== */

/* 1. Reset the atomic div to remove default 10px padding and force proper frame size */
.portfolio-card {
    position: relative !important;
    overflow: hidden !important;
    display: block !important;
    width: 100% !important;
    aspect-ratio: 4 / 3; /* Forces a neat portfolio grid card shape */
    padding: 0 !important; /* STRIPS THE DEFAULT 10PX ATOMIC PADDING */
    margin: 0 !important;
}

/* 2. Force the image container and raw image markup to fill edge-to-edge */
.portfolio-image,
.portfolio-image img,
.portfolio-card .portfolio-image canvas,
.portfolio-card .widget-image {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important; /* Crops cleanly to prevent stretching */
    display: block !important; /* Eliminates the default HTML text-line gap below images */
    padding: 0 !important;
    margin: 0 !important;
}

/* 3. Style and place the text box perfectly over the bottom boundary */
.portfolio-card .portfolio-image-popup-div {
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 10 !important;
    padding: 10px !important; /* Keeps padding inside the blue box text area */
    background-color: #0490FF !important; 


    /* Hide the box below the frame by default */
    transform: translateY(100%) !important;
    transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1) !important;
}

/* 4. Smoothly pull the blue text layout up when hovering anywhere on the card */
.portfolio-card:hover .portfolio-image-popup-div {
    transform: translateY(0%) !important;
}

/* 5. Ensure text inside the popup is white for good contrast */
.portfolio-image-popup-div h1,
.portfolio-image-popup-div h2,
.portfolio-image-popup-div h3,
.portfolio-image-popup-div h4,
.portfolio-image-popup-div h5,
.portfolio-image-popup-div h6,
.portfolio-image-popup-div p {
    color: #ffffff !important;
}

/* ==========================================================================
   DESIGN 2: FULL-SIZE OPAQUE OVERLAY + TEXT STAGGER + SLOW IMAGE ZOOM
   ========================================================================= */

/* 1. Reset outer frame crop */
.portfolio-card-fade {
    position: relative !important;
    overflow: hidden !important;
    display: block !important;
    width: 100% !important;
    aspect-ratio: 4 / 3;
    padding: 0 !important;
    margin: 0 !important;
    cursor: pointer;
}

/* 2. Setup the image zoom state - 1.2s smooth duration */
.portfolio-card-fade .portfolio-image,
.portfolio-card-fade .portfolio-image img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block !important;
    transition: transform 1.2s cubic-bezier(0.25, 1, 0.5, 1) !important;
}

/* Zoom the sibling image widget on parent hover */
.portfolio-card-fade:hover .portfolio-image img,
.portfolio-card-fade:hover .portfolio-image {
    transform: scale(1.1) !important;
}

/* 3. MODIFIED: STRETCH THE POPUP DIV FULL WIDTH/HEIGHT & ADD FLEX CENTERING */
.portfolio-card-fade .portfolio-image-popup-div {
    position: absolute !important;
    top: 0 !important;        /* Snap to top edge */
    left: 0 !important;       /* Snap to left edge */
    width: 100% !important;    /* Fill 100% width of the card */
    height: 100% !important;   /* Fill 100% height of the card */
    z-index: 10 !important;

    /* Center the internal text elements perfectly using flex layout */
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    align-items: center !important;
    text-align: center !important;
    padding: 30px !important;

    /* 
       SEMI-TRANSPARENT OPAQUE BACKDROP:
       rgba(0, 0, 0, 0.4) creates a 40% black overlay tint. 
       Adjust 0.4 up or down to make it darker or lighter.
    */
    background-color: rgba(0, 0, 0, 0.4) !important;

    /* Default Hidden States */
    opacity: 0 !important;
    pointer-events: none !important;
    transition: opacity 0.4s ease-in-out !important;
}

/* 4. Set text sizes and add a gap between headers */
.portfolio-card-fade .portfolio-image-popup-div h5 {
    font-size: 1.5rem !important;
    margin: 0 0 15px 0 !important; /* Forces 15px gap below header */
    transform: translateY(-20px) !important; 
    transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1) !important;
}

.portfolio-card-fade .portfolio-image-popup-div h6 {
    font-size: 1.1rem !important;
    margin: 0 !important;
    transform: translateY(20px) !important;  
    transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1) !important;
}

/* ==========================================================================
   HOVER TRIGGERS
   ========================================================================== */

/* Fade in the full-size opaque overlay container sibling */
.portfolio-card-fade:hover .portfolio-image-popup-div {
    opacity: 1 !important;
}

/* Return the h5 heading to its resting center spot on hover */
.portfolio-card-fade:hover .portfolio-image-popup-div h5 {
    transform: translateY(0) !important;
}

/* Return the h6 subheading to its resting center spot on hover */
.portfolio-card-fade:hover .portfolio-image-popup-div h6 {
    transform: translateY(0) !important;
}

/* Ensure all text elements inside the sibling popup are white */
.portfolio-image-popup-div h5,
.portfolio-image-popup-div h6 {
    color: #ffffff !important;
}

